from ortools.sat.python import cp_model
import json

def solve_warehouse_location():
    model = cp_model.CpModel()

    I = [1, 2]
    J = [1, 2, 3, 4, 5]

    construction_cost = {1: 1500, 2: 2000}

    demand = {1: 80, 2: 120, 3: 90, 4: 110, 5: 100}

    shipping_cost = {
        1: {1: 50, 2: 60, 3: 80, 4: 70, 5: 90},
        2: {1: 70, 2: 40, 3: 90, 4: 50, 5: 60}
    }

    open_vars = {}
    for i in I:
        open_vars[i] = model.NewBoolVar(f"open_{i}")

    assign_vars = {}
    for i in I:
        for j in J:
            assign_vars[(i, j)] = model.NewBoolVar(f"assign_{i}_{j}")

    for j in J:
        model.Add(sum(assign_vars[(i, j)] for i in I) == 1)

    for i in I:
        for j in J:
            model.Add(assign_vars[(i, j)] <= open_vars[i])

    construction_cost_expr = sum(construction_cost[i] * open_vars[i] for i in I)

    shipping_cost_expr = sum(
        shipping_cost[i][j] * demand[j] * 1000 * assign_vars[(i, j)]
        for i in I for j in J
    )

    total_cost = construction_cost_expr + shipping_cost_expr
    model.Minimize(total_cost)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 0

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_cost_value = int(solver.ObjectiveValue())

        centers_open = [int(solver.Value(open_vars[i])) for i in I]

        assignments = []
        for j in J:
            cluster_assignment = []
            for i in I:
                cluster_assignment.append(int(solver.Value(assign_vars[(i, j)])))
            assignments.append(cluster_assignment)

        print(json.dumps({
            "total_cost": total_cost_value,
            "centers_open": centers_open,
            "assignments": assignments
        }))
    else:
        print(json.dumps({
            "total_cost": 0,
            "centers_open": [],
            "assignments": []
        }))

if __name__ == "__main__":
    solve_warehouse_location()
